#include <stdio.h>
#include <stdlib.h>
int main(void) {
 size_t old_count = 2, new_count = 4;
 int *items = malloc(old_count * sizeof *items);
 if (items == NULL) return 1;
 items[0] = 10; items[1] = 20;
 int *grown = realloc(items, new_count * sizeof *items);
 if (grown == NULL) { free(items); return 1; }
 items = grown;
 items[2] = 30; items[3] = 40;
 printf("%d %d\n", items[0], items[3]);
 free(items);
 return 0;
}
